   108  struct flb_parser *flb_parser_create(const char *name, const char *format,
   109                                       const char *p_regex,
   110                                       const char *time_fmt, const char *time_key,
   111                                       const char *time_offset,
   112                                       int time_keep,
   113                                       struct flb_parser_types *types,
   114                                       int types_len,
   115                                       struct mk_list *decoders,
   116                                       struct flb_config *config)
   117  {
   118      int ret;
   119      int len;
   120      int diff = 0;
   121      int size;
   122      int is_epoch = FLB_FALSE;
   123      char *tmp;
   124      struct mk_list *head;
   125      struct flb_parser *p;
   126      struct flb_regex *regex;
   127
   128      /* Iterate current parsers and make sure the new one don't exists */
   129      mk_list_foreach(head, &config->parsers) {
   130          p = mk_list_entry(head, struct flb_parser, _head);
   131          if (strcmp(p->name, name) == 0) {
   132              flb_error("[parser] parser named '%s' already exists, skip.",
   133                        name);
   134              return NULL;
   135          }
   136      }
   137
   138      /* Allocate context */
   139      p = flb_calloc(1, sizeof(struct flb_parser));
   140      if (!p) {
   141          flb_errno();
   142          return NULL;
   143      }
   144      p->decoders = decoders;
   145      mk_list_add(&p->_head, &config->parsers);
   146
   147      /* Format lookup */
   148      if (strcasecmp(format, "regex") == 0) {
   149          p->type = FLB_PARSER_REGEX;
   150      }
   151      else if (strcasecmp(format, "json") == 0) {
   152          p->type = FLB_PARSER_JSON;
   153      }
   154      else if (strcmp(format, "ltsv") == 0) {
   155          p->type = FLB_PARSER_LTSV;
   156      }
   157      else if (strcmp(format, "logfmt") == 0) {
   158          p->type = FLB_PARSER_LOGFMT;
   159      }
   160      else {
   161          flb_error("[parser:%s] Invalid format %s", name, format);
   162          flb_free(p);
   163          return NULL;
   164      }
   165
   166      if (p->type == FLB_PARSER_REGEX) {
   167          if (!p_regex) {
   168              flb_error("[parser:%s] Invalid regex pattern", name);
   169              flb_free(p);
   170              return NULL;
   171          }
   172
   173          regex = flb_regex_create(p_regex);
   174          if (!regex) {
   175              flb_error("[parser:%s] Invalid regex pattern %s", name, p_regex);
   176              flb_free(p);
   177              return NULL;
   178          }
   179          p->regex = regex;
   180          p->p_regex = flb_strdup(p_regex);
   181      }
   182
   183      p->name = flb_strdup(name);
   184
   185      if (time_fmt) {
   186          p->time_fmt_full = flb_strdup(time_fmt);
   187          p->time_fmt = flb_strdup(time_fmt);
   188
   189          /* Check if the format is considering the year */
   190          if (strstr(p->time_fmt, "%Y") || strstr(p->time_fmt, "%y")) {
   191              p->time_with_year = FLB_TRUE;
   192          }
   193          else if (strstr(p->time_fmt, "%s")) {
   194              is_epoch = FLB_TRUE;
   195              p->time_with_year = FLB_TRUE;
   196          }
   197          else {
   198              size = strlen(p->time_fmt);
   199              p->time_with_year = FLB_FALSE;
   200              p->time_fmt_year = flb_malloc(size + 4);
   201              if (!p->time_fmt_year) {
   202                  flb_errno();
   203                  flb_parser_destroy(p);
   204                  return NULL;
   205              }
   206
   207              /* Append the year at the beginning */
   208              tmp = p->time_fmt_year;
   209              *tmp++ = '%';
   210              *tmp++ = 'Y';
   211              *tmp++ = ' ';
   212
   213              memcpy(tmp, p->time_fmt, size);
   214              tmp += size;
   215              *tmp++ = '\0';
   216          }
   217
   218          /* Check if the format contains a timezone (%z) */
   219          if (strstr(p->time_fmt, "%z") || strstr(p->time_fmt, "%Z") ||
   220              strstr(p->time_fmt, "%SZ") || strstr(p->time_fmt, "%S.%LZ")) {
   221  #if defined(FLB_HAVE_GMTOFF) || !defined(FLB_HAVE_SYSTEM_STRPTIME)
   222              p->time_with_tz = FLB_TRUE;
   223  #else
   224              flb_error("[parser] timezone offset not supported");
   225              flb_error("[parser] you cannot use %%z/%%Z on this platform");
   226              flb_parser_destroy(p);
   227              return NULL;
   228  #endif
   229          }
   230
   231          /*
   232           * Check if the format expect fractional seconds
   233           *
   234           * Since strptime(3) does not support fractional seconds, this
   235           * requires a workaround/hack in our parser. This is a known
   236           * issue and addressed in different ways in other languages.
   237           *
   238           * The following links are a good reference:
   239           *
   240           * - http://stackoverflow.com/questions/7114690/how-to-parse-syslog-timestamp
   241           * - http://code.activestate.com/lists/python-list/521885/
   242           */
   243          if (is_epoch == FLB_TRUE) {
   244              tmp = strstr(p->time_fmt, "%s.%L");
   245          }
   246          else if (p->time_with_year == FLB_TRUE) {
   247              tmp = strstr(p->time_fmt, "%S.%L");
   248          }
   249          else {
   250              tmp = strstr(p->time_fmt_year, "%s.%L");
   251
   252              if (tmp == NULL) {
   253                  tmp = strstr(p->time_fmt_year, "%S.%L");
   254              }
   255          }
   256          if (tmp) {
   257              tmp[2] = '\0';
   258              p->time_frac_secs = (tmp + 5);
   259          }
   260          else {
   261              /* same as above but with comma seperator */
   262              if (p->time_with_year == FLB_TRUE) {
   263                  tmp = strstr(p->time_fmt, "%S,%L");
   264              }
   265              else {
   266                  tmp = strstr(p->time_fmt_year, "%s,%L");
   267
   268                  if (tmp == NULL) {
   269                      tmp = strstr(p->time_fmt_year, "%S,%L");
   270                  }
   271              }
   272              if (tmp) {
   273                  tmp[2] = '\0';
   274                  p->time_frac_secs = (tmp + 5);
   275              }
   276              else {
   277                  p->time_frac_secs = NULL;
   278              }
   279          }
   280
   281          /* Optional fixed timezone offset */
   282          if (time_offset) {
   283              diff = 0;
   284              len = strlen(time_offset);
   285              ret = flb_parser_tzone_offset(time_offset, len, &diff);
   286              if (ret == -1) {
   287                  flb_parser_destroy(p);
   288                  return NULL;
   289              }
   290              p->time_offset = diff;
   291          }
   292      }
   293
   294      if (time_key) {
   295          p->time_key = flb_strdup(time_key);
   296      }
   297
   298      p->time_keep = time_keep;
   299      p->types = types;
   300      p->types_len = types_len;
   301      return p;
   302  }
