   103  static int decode_mysql_quoted(struct flb_parser_dec *dec,
   104                                 char *in_buf, size_t in_size,
   105                                 char **out_buf, size_t *out_size, int *out_type)
   106  {
   107      int len;
   108      if(in_size < 2) {
   109          dec->buffer[0] = in_buf[0];
   110          dec->buffer[1] = 0;
   111          *out_buf = dec->buffer;
   112          *out_size = in_size;
   113          *out_type = TYPE_OUT_STRING;
   114      }
   115      else if(in_buf[0] == '\'' && in_buf[in_size-1] == '\'') {
   116          len = flb_mysql_unquote_string(in_buf+1, in_size-2, &dec->buffer);
   117          *out_buf = dec->buffer;
   118          *out_size = len;
   119          *out_type = TYPE_OUT_STRING;
   120      }
   121      else if(in_buf[0] == '\"' && in_buf[in_size-1] == '\"') {
   122          len = flb_mysql_unquote_string(in_buf+1, in_size-2, &dec->buffer);
   123          *out_buf = dec->buffer;
   124          *out_size = len;
   125          *out_type = TYPE_OUT_STRING;
   126      }
   127      else {
   128          memcpy(dec->buffer, in_buf, in_size);
   129          dec->buffer[in_size] = 0;
   130          *out_buf = dec->buffer;
   131          *out_size = in_size;
   132          *out_type = TYPE_OUT_STRING;
   133      }
   134
   135      return 0;
   136  }
