   138  static int merge_record_and_extra_keys(const char *in_buf, size_t in_size,
   139                                         const char *extra_buf, size_t extra_size,
   140                                         char **out_buf, size_t *out_size)
   600      struct flb_split_entry *action;
   601      struct flb_parser_dec *dec;
   602      struct flb_parser_dec_rule *dec_rule;
   603
   604      /* Global list to be referenced by parent parser definition */
   605      list = flb_malloc(sizeof(struct mk_list));
   606      if (!list) {
   607          flb_errno();
   608          return NULL;
   609      }
   610      mk_list_init(list);
   611
   612
   613      mk_list_foreach(head, &section->entries) {
   614          entry = mk_list_entry(head, struct mk_rconf_entry, _head);
   615
   616          /* Lookup for specific Decode rules */
   617          if (strcasecmp(entry->key, "Decode_Field") == 0) {
   618              type = FLB_PARSER_DEC_DEFAULT;
   619          }
   620          else if (strcasecmp(entry->key, "Decode_Field_As") == 0) {
   621              type = FLB_PARSER_DEC_AS;
   622          }
   623          else {
   624              continue;
   625          }
   626
   627          /* Split the value */
   628          split = flb_utils_split(entry->val, ' ', 3);
   629          if (!split) {
   630              flb_error("[parser] invalid number of parameters in decoder");
   631              flb_parser_decoder_list_destroy(list);
   632              return NULL;
   633          }
   634
   635          /* We expect at least two values: decoder name and target field */
   636          size = mk_list_size(split);
   637          if (size < 2) {
   638              flb_error("[parser] invalid number of parameters in decoder");
   639              flb_utils_split_free(split);
   640              flb_parser_decoder_list_destroy(list);
   641              return NULL;
   642          }
   643
   644          /*
   645           * Get the rule/entry references:
   646           *
   647           * decoder: specify the backend that handle decoding (json, escaped..)
   648           * field  : the 'key' where decoding should happen
   649           * action : optional rules to follow on success or failure
   650           */
   651          decoder = mk_list_entry_first(split, struct flb_split_entry, _head);
   652          field = mk_list_entry_next(&decoder->_head, struct flb_split_entry,
   653                                     _head, list);
   654          if (size >= 3) {
   655              action = mk_list_entry_next(&field->_head, struct flb_split_entry,
   656                                          _head, list);
   657          }
   658          else {
   659              action = NULL;
   660          }
   661
   662          /* Get decoder */
   663          if (strcasecmp(decoder->value, "json") == 0) {
   664              backend = FLB_PARSER_DEC_JSON;
   665          }
   666          else if (strcasecmp(decoder->value, "escaped") == 0) {
   667              backend = FLB_PARSER_DEC_ESCAPED;
   668          }
   669          else if (strcasecmp(decoder->value, "escaped_utf8") == 0) {
   670              backend = FLB_PARSER_DEC_ESCAPED_UTF8;
   671          }
   672          else if (strcasecmp(decoder->value, "mysql_quoted") == 0) {
   673              backend = FLB_PARSER_DEC_MYSQL_QUOTED;
   674          }
   675          else {
   676              flb_error("[parser] field decoder '%s' unknown", decoder->value);
   677              flb_utils_split_free(split);
   678              flb_parser_decoder_list_destroy(list);
   679              return NULL;
   680          }
   681
   682          /* Get the parent decoder that will hold the rules defined */
   683          dec = get_decoder_key_context(field->value, strlen(field->value), list);
   684          if (!dec) {
   685              /* Unexpected error */
   686              flb_error("[parser] unexpected error, could not get a decoder");
   687              flb_utils_split_free(split);
   688              flb_parser_decoder_list_destroy(list);
   689              return NULL;
   690          }
   691
   692          /* Create decoder context */
   693          dec_rule = flb_calloc(1, sizeof(struct flb_parser_dec_rule));
   694          if (!dec_rule) {
   695              flb_errno();
   696              flb_utils_split_free(split);
   697              flb_parser_decoder_list_destroy(list);
   698              return NULL;
   699          }
   700
   701          if (type == FLB_PARSER_DEC_DEFAULT) {
   702              dec->add_extra_keys = FLB_TRUE;
   703          }
   704
   705          dec_rule->type = type;
   706          dec_rule->backend = backend;
   707          if (action) {
   708              if (strcasecmp(action->value, "try_next") == 0) {
   709                  dec_rule->action = FLB_PARSER_ACT_TRY_NEXT;
   710              }
   711              else if (strcasecmp(action->value, "do_next") == 0) {
   712                  dec_rule->action = FLB_PARSER_ACT_DO_NEXT;
   713              }
   714              else {
   715                  dec_rule->action = FLB_PARSER_ACT_NONE;
   716              }
   717          }
   718
   719          /* Remove temporary split */
   720          flb_utils_split_free(split);
   721          mk_list_add(&dec_rule->_head, &dec->rules);
   722          c++;
   723      }
   724
   725      if (c == 0) {
   726          flb_free(list);
   727          return NULL;
   728      }
   729
   730      return list;
   731  }
