   733  int flb_parser_decoder_list_destroy(struct mk_list *list)
   734  {
   735      int c = 0;
   736      struct mk_list *head;
   737      struct mk_list *r_head;
   738      struct mk_list *tmp;
   739      struct mk_list *r_tmp;
   740      struct flb_parser_dec *dec;
   741      struct flb_parser_dec_rule *dec_rule;
   742
   743      mk_list_foreach_safe(head, tmp, list) {
   744          dec = mk_list_entry(head, struct flb_parser_dec, _head);
   745
   746          /* Destroy rules */
   747          mk_list_foreach_safe(r_head, r_tmp, &dec->rules) {
   748              dec_rule = mk_list_entry(r_head, struct flb_parser_dec_rule,
   749                                       _head);
   750              mk_list_del(&dec_rule->_head);
   751              flb_free(dec_rule);
   752          }
   753
   754          mk_list_del(&dec->_head);
   755          flb_sds_destroy(dec->key);
   756          flb_sds_destroy(dec->buffer);
   757          flb_free(dec);
   758          c++;
   759      }
   760
   761      flb_free(list);
   762      return c;
   763  }
